const TimeUpdateDay  = ({
	data,
	lunch,
	index,
	dayName,
	confirm,
	payrate,
	keyId
	
 }) => {
	

	const closeDetails = (v) =>{
		let lastTimeCallModal = getStore("day_last"+keyId) || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("day_last"+keyId, Date.now()+490);
			let nobj = Object.assign({}, data, v);
			confirm(keyId,nobj);
		}
	}


	

	

	let regular = data.end - data.start - lunch;
	let payRate = payrate/60 * (regular);
	let hh = parseTimeH(regular);

	return (
		<>
		{index>0?
		<>
			<div className="flexSpace"/>
			<div className="left_border"/>
			<div className="flexSpace"/>
		</>
		:null}
		<div className={`lbl_h_dtls`}  style={{marginTop:8, textAlign: "left"}} >
			<div className="dayHour _dsplFlx">
				<div className="flexSpace"/>
				<div style={{marginRight: 12}}>
					{`${dayName}`}
				</div>
				<div className="flexSpace"/>
				<CheckBoxSlide
					initvalue={data?.["active"]}
					keyCode={57}
					updChange={(e)=>closeDetails({active: e})}
				/>
				<div className="flexSpace"/>
			</div>
			{data?.["active"]? 
			<div className="dayHour">
				<div>
					{`${hh} - $${payRate?payRate.toFixed(2):"0.00"}`}
				</div>
			</div>
			:null}
			{data?.["active"]? 
			<div className="_dsplFlx information_detail "  >
				<div className="flexSpace"/>
				{data.startMode?
					<TimeCardView 
						data={data} 
						field={"start"}
						icon={"startMode"}
						confirm={closeDetails} 
					/>
					:
					<TimeUpdateView 
						data={data} 
						field={"start"} 
						confirm={closeDetails} 
					/>
				}
				<div className="flexSpace"/>
				-
				<div className="flexSpace"/>
				{data.endMode?
					<TimeCardView 
						data={data} 
						field={"end"}
						icon={"endMode"}
						confirm={closeDetails} 
					/>
					:
					<TimeUpdateView 
						data={data} 
						field={"end"} 
						confirm={closeDetails} 
					/>
				}
				<div className="flexSpace"/>
			</div>
			:null}
		</div>
		</>
		)
 }


const TimeUpdateView  = ({
	data,
	sA,
	field,
	value,
	dayName,
	confirm,
	timezone,
	meridiem,
	hour, 
	minute
 }) => {
	const [show, setShow] = useState(false);

	const onFocusChange = () =>{
		setShow(!show);
	}

	const onTimeChange = (v) =>{
		let lastTimeCallModal = getStore("day_last") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("day_last", Date.now()+490);
			let tm = v.hour*60+v.minute*1;
			confirm({[field]:tm});
		}
	}




	const trigger = () =>{
		return(<div></div>)
	}
	
	const toogleShow = () =>{
		setShow(!show);
	}



	
	let hhmm =data?.[field]? parseTimeH(data?.[field]) : null;

	return (

		<div   >
			<div className=" payments hour" onClick={toogleShow}>
				<Svg
					name={"timer_outline2"} 
					size={22}
					color={"#757575"}
				/>
				{parseTimeH(data?.[field])}
			</div>
			{show?
 			<div className="time_picker_wrapper centerMdl">
				<TimePicker
					trigger={trigger}
					focused={show}
				
					onFocusChange={onFocusChange}
					onTimeChange={onTimeChange}
					showTimezone={false}
					time={hhmm ? `${hhmm}` : null}
				/>
			</div>
			:null}
		</div>

	) 
 }


