export const parseTimeH  = ( v)  => {
	if(!v){
		return null;
	}
	let hh = Math.floor(v/60);
	let mm = v - (hh*60);
	return  `${hh>9?hh:"0"+hh}:${mm>9?mm:"0"+mm}`;
}





export const hourlyParse  = ( hourly , payrate, lunch, overtime)  => {

	let hoursTt = 0;
	let hoursAfterLunch = 0;
	let overtimeHours = 0;
	let payrateMin = payrate/60;
	

	ObjectKeys(hourly).map((day,inD)=>{
		if(hourly?.[day]?.active){

			let minT = hourly?.[day]?.end - hourly?.[day]?.start;
			
			hoursTt += minT
			hoursAfterLunch +=minT - lunch*1;
		}
	})
	
	if(overtime && hoursAfterLunch>2400){
		overtimeHours = hoursAfterLunch - 2400;
		hoursAfterLunch = 2400;
	}

	
	let info = {
		hoursTt,
		regularHours: hoursAfterLunch,
		regularPayment: hoursAfterLunch*payrateMin,
		overtimeHours,
		overtimePayment: overtimeHours*payrateMin*1.5
	}
	return info;

}

		


































